/**
 * Brand mark: a round badge with a snow-capped peak, a green ridge behind it,
 * the sun, and a zig-zag trail. Keep in sync with src/app/icon.svg
 * (the browser-tab version, regenerated by `npm run icons`).
 */
export function LogoMark({ className = "h-10 w-10", trail = true }: { className?: string; trail?: boolean }) {
  return (
    // Rounded with CSS (not an SVG clipPath) so several logos on one page don't share an id.
    <svg viewBox="0 0 64 64" className={`overflow-hidden rounded-full ${className}`} aria-hidden>
      <g>
        <rect width="64" height="64" fill="#3d4530" />
        <circle cx="45" cy="20" r="6.5" fill="#e9b949" />
        {/* Back ridge */}
        <path d="M2 50 L22 30 L30 38 L40 25 L64 50 V64 H2Z" fill="#8e9873" />
        {/* Front peak with snow cap and shaded side */}
        <path d="M-2 56 L26 18 L54 56Z" fill="#f5eedd" />
        <path d="M26 18 L54 56 H34 L31 38Z" fill="#d6caa9" />
        <path d="M26 18 L33 27.5 L29.5 26 L26.5 29.5 L23 26 L19.5 27.5Z" fill="#fff" />
        {/* Ground */}
        <path d="M-2 54 Q32 47 66 54 V66 H-2Z" fill="#5f6a47" />
        {trail && (
          <path
            d="M18 55 L27 49.5 L21.5 45 L28 40.5 L24 36"
            fill="none"
            stroke="#5f6a47"
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray="0.1 3.4"
          />
        )}
      </g>
    </svg>
  );
}
